package com.muoniumplayer.configskija.settings;

import com.muoniumplayer.configskija.ui.*;
import com.muoniumplayer.configskija.ui.Geometry.Rect;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;

/** Actual key/pointer/render events, using the same controller that ConfigView can directly own. */
public final class TextInputHarness {
    private static int checks;
    private static void check(boolean condition, String message) { checks++; if (!condition) throw new AssertionError(message); }
    private static void equal(Object a, Object b, String message) { check(Objects.equals(a, b), message + ": " + a + " != " + b); }
    private static void near(double a, double b, String message) { check(Math.abs(a - b) < 1e-6, message + ": " + a + " != " + b); }
    private static final class Test extends SettingsHarness.Context {
        Test() { super(new SettingsHarness.Fixture(), false); }
        void begin() { hits.clear(); painter.rectangles.clear(); painter.texts.clear(); input.beginFrame(this); }
        void end() { input.endFrame(this); }
        void field(String id, TextEdit edit, Rect r, TextInputController.Style style, Consumer<String> changed, Runnable blur) { bareTextField(id, edit, r, style, changed, blur); }
        void point(double px, double py) { x = px; y = py; }
        void down(double px, double py) { point(px, py); input.pointerDown(this, 0); }
        void up() { input.pointerUp(this, 0); }
        void key(ConfigView.Key key, String typed, boolean control, boolean shift) { input.key(this, key, typed, control, shift, false); }
        void key(ConfigView.Key key) { key(key, "", false, false); }
    }
    private static TextInputController.Style single() { return new TextInputController.Style(10).lineHeight(12); }
    private static TextEdit editor(String text, boolean multiline) { TextEdit edit = new TextEdit(); edit.multiline(multiline); edit.text(text); return edit; }
    private static void model() {
        TextEdit edit = editor("first second", false); edit.move(-1, false, true); equal(edit.cursor(), 6, "Ctrl-left reaches previous word"); edit.move(1, false, true); equal(edit.cursor(), 12, "Ctrl-right reaches next word");
        edit.text("a😀b"); edit.selection(2, 2); equal(edit.cursor(), 1, "selection never splits surrogate"); edit.move(1, true, false); equal(edit.selectedText(), "😀", "Shift extends by Unicode grapheme"); edit.insert("e\u0301"); edit.delete(true, false); equal(edit.text(), "ab", "backspace removes combining sequence");
        edit.text("👩‍💻!"); edit.edge(false, false); edit.move(1, false, false); equal(edit.cursor(), "👩‍💻".length(), "ZWJ emoji moves as one grapheme"); edit.delete(true, false); equal(edit.text(), "!", "ZWJ emoji delete is indivisible");
        edit.multiline(true); edit.text("ab\r\n😀x\n"); equal(edit.text(), "ab\n😀x\n", "multiline normalizes CRLF"); equal(edit.lineCount(), 3, "trailing LF creates final line"); equal(edit.position(1, 1), 5, "row column addresses supplementary code point"); edit.selection(5, 5); equal(edit.line(edit.cursor()), 1, "logical row"); equal(edit.column(edit.cursor()), 1, "logical code point column"); edit.vertical(1, false); equal(edit.cursor(), edit.text().length(), "vertical clamps to empty final line"); edit.vertical(-1, false); equal(edit.cursor(), 5, "preferred column survives shorter lines");
        edit.text("one\ntwo"); edit.selection(5, 5); edit.lineEdge(false, false); equal(edit.cursor(), 4, "Home logical line start"); edit.lineEdge(true, true); equal(edit.selectedText(), "two", "Shift End selects logical remainder"); edit.edge(false, false); equal(edit.cursor(), 0, "Ctrl Home document start");
        edit.selectAll(); edit.insert("new\nline"); check(edit.undo(), "text local undo exists"); equal(edit.text(), "one\ntwo", "undo restores selection replacement"); check(edit.redo(), "text local redo exists"); equal(edit.text(), "new\nline", "redo restores edit");
        edit.multiline(false); equal(edit.text(), "newline", "switching single-line filters line controls"); edit.text("abc"); edit.delete(true, false); edit.undo(); equal(edit.cursor(), 3, "delete undo restores the original caret instead of temporary deletion selection"); edit.text("x".repeat(4095)); edit.insert("😀"); equal(edit.text().length(), 4095, "legacy 4096 limit remains code point safe"); edit.limit(Integer.MAX_VALUE); edit.text("x".repeat(5000)); equal(edit.text().length(), 5000, "bare fields have no invented 4096 ceiling");
    }
    private static void pointerAndSelection() {
        Test t = new Test(); TextEdit edit = editor("alpha beta\ngamma", true); Rect r = new Rect(100, 100, 180, 48); TextInputController.Style style = single().multiline(true); AtomicInteger blur = new AtomicInteger();
        t.begin(); t.field("text", edit, r, style, value -> {}, blur::incrementAndGet); t.end();
        t.down(100 + 3 * 5.2, 104); t.hit("text").action().run(); check(!edit.selected(), "one physical down routed through hit registry is not mistaken for a double click"); t.up(); equal(edit.cursor(), 3, "click measured cursor position");
        t.now += 1; t.down(100 + 5.2, 104); t.input.pointerMove(t, 100 + 4 * 5.2, 104); t.up(); equal(edit.selectedText(), "lph", "pointer drag selects measured text");
        t.now += 1; t.down(100 + 2 * 5.2, 104); t.up(); t.now += .1; t.down(100 + 2 * 5.2, 104); t.up(); equal(edit.selectedText(), "alpha", "double click selects word");
        t.input.pointerMove(t, 100 + 9 * 5.2, 104); // released drag must do nothing
        equal(edit.selectedText(), "alpha", "released selection no longer follows pointer");
        t.now += .1; t.down(100 + 2 * 5.2, 104); t.up(); equal(edit.selectedText(), "alpha beta\n", "triple click selects logical line including separator");
        t.now += 1; t.down(110, 116); t.up(); equal(edit.line(edit.cursor()), 1, "multi-line y coordinate selects correct row"); t.down(50, 50); equal(blur.get(), 1, "outside click submits once"); check(!edit.focused && !t.input.focused(), "outside click releases focus"); t.input.blur(t); equal(blur.get(), 1, "repeat blur does not double-submit");
        t.begin(); style.clip = new Rect(120, 100, 40, 24); t.field("text", edit, r, style, value -> {}, blur::incrementAndGet); t.end(); check(!t.input.pointerDown(t, 0), "clipped-away area is not focusable");
    }
    private static void keyboardSessions() {
        Test t = new Test(); TextEdit edit = editor("start", false); AtomicInteger changed = new AtomicInteger(), blur = new AtomicInteger(), submit = new AtomicInteger(); Rect r = new Rect(20, 20, 100, 20);
        t.begin(); t.input.field(t, "text", edit, r, single(), value -> changed.incrementAndGet(), blur::incrementAndGet, submit::incrementAndGet); t.end(); t.input.focus(t, "text", true);
        t.key(ConfigView.Key.NONE, "draft", false, false); equal(edit.text(), "draft", "typed characters replace selection"); t.key(ConfigView.Key.ESCAPE); equal(edit.text(), "start", "Escape reverts focus-session value"); equal(blur.get(), 1, "Escape finishes once"); equal(submit.get(), 0, "Escape never calls submit"); check(!t.input.focused(), "Escape releases keyboard");
        t.input.focus(t, "text", true); t.key(ConfigView.Key.NONE, "saved", false, false); t.key(ConfigView.Key.ENTER); equal(edit.text(), "saved", "Enter keeps draft"); equal(blur.get(), 2, "Enter invokes blur once"); equal(submit.get(), 1, "Enter invokes submit once");
        t.input.focus(t, "text", false); t.key(ConfigView.Key.A, "", true, false); t.key(ConfigView.Key.C, "", true, false); equal(t.host.clipboard, "saved", "Ctrl C clipboard selection"); t.key(ConfigView.Key.X, "", true, false); equal(edit.text(), "", "Ctrl X cuts"); t.key(ConfigView.Key.V, "", true, false); equal(edit.text(), "saved", "Ctrl V pastes"); t.key(ConfigView.Key.Z, "", true, false); equal(edit.text(), "", "Ctrl Z is local editor undo"); t.key(ConfigView.Key.Z, "", true, true); equal(edit.text(), "saved", "Ctrl Shift Z redo");
        t.key(ConfigView.Key.HOME); equal(edit.cursor(), 0, "Home before first glyph"); t.key(ConfigView.Key.RIGHT, "", false, true); equal(edit.selectedText(), "s", "Shift arrow extends"); t.key(ConfigView.Key.END, "", false, true); equal(edit.selectedText(), "saved", "Shift End keeps anchor");
        t.input.blur(t); t.begin(); TextInputController.Style filtered = single().filter(value -> value.replaceAll("[^0-9]", "")); t.field("number", edit, r, filtered, value -> changed.incrementAndGet(), blur::incrementAndGet); t.end(); t.input.focus(t, "number", true); t.key(ConfigView.Key.NONE, "a12b34", false, false); equal(edit.text(), "1234", "filter applies before callback"); equal(edit.cursor(), 4, "filter maps caret into filtered prefix");
    }
    private static void singleLinePasteTransformation() {
        Test t = new Test(); TextEdit edit = editor("", false); Rect bounds = new Rect(10, 10, 200, 15); t.begin(); t.field("single", edit, bounds, single(), value -> {}, null); t.end(); t.input.focus(t, "single", false); t.host.clipboard = "a\r\nb"; t.key(ConfigView.Key.V, "", true, false); equal(edit.text(), "a\r\nb", "single-line paste retains raw CRLF as original property value"); t.begin(); t.field("single", edit, bounds, single(), value -> {}, null); t.end(); equal(t.input.layout(t, "single").lines().size(), 1, "single-line paste renders one visual row"); check(t.painter.texts.stream().anyMatch(text -> text.text().equals("a\ufeff b")), "single-line visual transformation maps CR to zero-width and LF to space"); t.key(ConfigView.Key.A, "", true, false); t.key(ConfigView.Key.C, "", true, false); equal(t.host.clipboard, "a\r\nb", "copy returns raw pasted separators rather than transformed display");
    }
    private static void layoutAndNavigation() {
        Test t = new Test(); TextEdit edit = editor("abcdef\nxy\nabcdef", true); Rect r = new Rect(20, 20, 25, 60); TextInputController.Style style = single().multiline(true); style.softWrap = true;
        t.begin(); t.field("multi", edit, r, style, value -> {}, null); t.end(); TextInputController.Layout layout = t.input.layout(t, "multi"); equal(layout.lines().size(), 5, "soft wrapping and logical newlines share measured layout");
        t.input.focus(t, "multi", false); edit.selection(2, 2); t.key(ConfigView.Key.DOWN); equal(edit.cursor(), 6, "Down preserves x across wrapped row"); t.key(ConfigView.Key.DOWN); equal(edit.cursor(), 9, "Down clamps at short logical row"); t.key(ConfigView.Key.DOWN); equal(edit.cursor(), 12, "preferred x restored on wider following row"); t.key(ConfigView.Key.HOME); equal(edit.cursor(), 10, "Home uses visual wrapped line start"); t.key(ConfigView.Key.END, "", false, true); equal(edit.selectedText(), "abcd", "Shift End uses current visual row end"); t.key(ConfigView.Key.HOME, "", true, false); equal(edit.cursor(), 0, "Ctrl Home ignores wrapping"); t.key(ConfigView.Key.END, "", true, false); equal(edit.cursor(), edit.text().length(), "Ctrl End document end");
        t.key(ConfigView.Key.ENTER); check(edit.text().endsWith("\n"), "multiline Enter inserts LF"); check(t.input.focused(), "multiline Enter retains focus"); t.key(ConfigView.Key.ENTER, "", true, false); check(!t.input.focused(), "Ctrl Enter submits multiline field");
        TextEdit overflow = editor("01234567890123456789", false); t.begin(); t.field("overflow", overflow, new Rect(10, 10, 30, 12), single(), value -> {}, null); t.end(); t.input.focus(t, "overflow", false); t.key(ConfigView.Key.END); Rect caret = t.input.caretRect(t); check(caret.x() >= 10 && caret.right() <= 40, "caret scrolls into narrow single-line viewport"); t.key(ConfigView.Key.HOME); near(t.input.caretRect(t).x(), 10, "Home scrolls back to start");
        TextEdit wrapped = editor("one two three four", true); TextInputController.Layout pure = TextInputController.layout(wrapped, 45, 10, 12, true, value -> value.length() * 5d); check(pure.lines().size() >= 2, "line-break measurement wraps at words"); equal(pure.lines().get(0).end(), 8, "word-safe break chooses latest fitting boundary");
    }
    private static void tabAndModal() {
        Test t = new Test(); TextEdit a = editor("A", false), b = editor("B", false), c = editor("C", false); AtomicInteger blurs = new AtomicInteger();
        t.begin(); t.field("a", a, new Rect(0, 0, 50, 12), single(), value -> {}, blurs::incrementAndGet); TextInputController.Style disabled = single(); disabled.enabled = false; t.field("b", b, new Rect(0, 20, 50, 12), disabled, value -> {}, null); t.field("c", c, new Rect(0, 40, 50, 12), single(), value -> {}, blurs::incrementAndGet); t.end();
        t.key(ConfigView.Key.TAB); equal(t.input.focusedId(), "a", "Tab enters first enabled field"); t.key(ConfigView.Key.TAB); equal(t.input.focusedId(), "c", "Tab skips disabled fields"); t.key(ConfigView.Key.TAB, "", false, true); equal(t.input.focusedId(), "a", "Shift Tab goes back"); equal(blurs.get(), 2, "Tab commits previous field exactly once");
        t.begin(); t.field("a", a, new Rect(0, 0, 50, 12), single(), value -> {}, blurs::incrementAndGet); t.input.pushScope(t, "popup", true); t.field("popup", b, new Rect(0, 20, 50, 12), single(), value -> {}, null); t.input.popScope(); t.end(); check(!a.focused, "modal scope releases background focus"); t.key(ConfigView.Key.TAB); equal(t.input.focusedId(), "popup", "modal Tab cannot reach underlying page");
        t.begin(); t.field("a", a, new Rect(0, 0, 50, 12), single(), value -> {}, blurs::incrementAndGet); t.end(); check(!t.input.focused(), "disappeared popup field releases keyboard");
        a.focused = true; t.begin(); t.field("a", a, new Rect(0, 0, 50, 12), single(), value -> {}, blurs::incrementAndGet); t.end(); equal(t.input.focusedId(), "a", "programmatic focused flag is adopted"); t.input.clear(t); check(!a.focused && !t.input.focused(), "screen close clears editor ownership");
        t.begin(); t.field("c", c, new Rect(0, 0, 50, 12), single(), value -> {}, null); t.field("a", a, new Rect(0, 20, 50, 12), single(), value -> {}, null); t.end(); t.key(ConfigView.Key.TAB); equal(t.input.focusedId(), "c", "Tab uses new visual registration order after reorder"); t.key(ConfigView.Key.TAB); equal(t.input.focusedId(), "a", "new visual order next field");
    }
    private static void cleanupAndScrolling() {
        Test t = new Test(); TextEdit edit = editor("1\n2\n3\n4\n5\n6", true); AtomicInteger blur = new AtomicInteger(); TextInputController.Style style = single().multiline(true); Rect r = new Rect(10, 10, 50, 24);
        t.begin(); t.field("scroll", edit, r, style, value -> {}, blur::incrementAndGet); t.end(); t.input.focus(t, "scroll", false); t.key(ConfigView.Key.END, "", true, false); Rect caret = t.input.caretRect(t); check(caret.y() >= 10 && caret.bottom() <= 34, "multiline caret scrolls to last line");
        t.point(20, 20); check(t.input.wheel(t, 1), "wheel scrolls overflow inside multiline viewport"); t.down(15, 12); t.input.pointerMove(t, 15, 200); t.up(); check(edit.selectedText().contains("\n"), "dragging beyond viewport scrolls and selects multiple lines");
        style.enabled = false; t.begin(); t.field("scroll", edit, r, style, value -> {}, blur::incrementAndGet); t.end(); equal(blur.get(), 1, "disabled active field commits once and releases ownership"); check(!t.input.focused(), "disabled field cannot keep focus");
        style.enabled = true; t.begin(); t.field("scroll", edit, r, style, value -> {}, blur::incrementAndGet); t.end(); t.input.focus(t, "scroll", false); t.begin(); t.end(); equal(blur.get(), 2, "unregistered field submits once on removal"); check(!t.input.focused(), "unregistered field cannot steal future keyboard input");
        t.begin(); t.field("right", edit, r, new TextInputController.Style(12).lineHeight(14), value -> {}, null); t.end(); t.now += 2; t.down(12, 12); t.up(); t.input.blur(t); check(t.painter.texts.stream().anyMatch(text -> text.size() == 12), "12sp opacity/speed fields retain their own font size");
    }
    private static void realViewIntegration() {
        SettingsHarness.Fixture host = new SettingsHarness.Fixture(); com.muoniumplayer.configskija.model.ConfigHost.Option option = host.add("actual", com.muoniumplayer.configskija.model.ConfigHost.Kind.CHOICE, "abcd ef"); host.styles.get("actual").visualizer = com.muoniumplayer.configskija.ui.settings.SettingsSchema.Visualizer.TEXT; host.category("cat", "Category", option);
        com.muoniumplayer.configskija.model.UiPreferences prefs = new com.muoniumplayer.configskija.model.UiPreferences(Map.of("instantSearch", "false", "guiOpenAnimation", "false"), () -> {}); ConfigView view = new ConfigView(host, prefs); view.register(com.muoniumplayer.configskija.model.Navigation.Page.SETTINGS, new com.muoniumplayer.configskija.ui.settings.SettingsPage(false)); view.navigate(new com.muoniumplayer.configskija.model.Navigation.Route(com.muoniumplayer.configskija.model.Navigation.Page.SETTINGS, "cat")); SettingsHarness.TracePainter painter = new SettingsHarness.TracePainter();
        view.frame(painter, 1391, 700, -100, -100, 1); view.frame(painter, 1391, 700, -100, -100, 2); Rect field = view.hitBounds().get("settings.text.actual"); check(field != null, "actual ConfigView registers settings bare field"); double targetX = field.x() + painter.measure("ab", 14, false); Geometry.Point screen = view.viewport().screen(targetX, field.y() + 4); check(view.pointerDown(screen.x(), screen.y(), 0, false, false, false), "actual ConfigView consumes input down"); view.pointerUp(screen.x(), screen.y(), 0); TextEdit active = view.textInputController().focusedEdit(); check(active != null, "actual ConfigView owns focused text input"); equal(active.cursor(), 2, "actual transformed click reaches measured caret"); check(!active.selected(), "actual ConfigView hit dispatch leaves single click unselected");
        view.key(ConfigView.Key.NONE, "Z", false, false, false); equal(host.values.get("actual"), "abZcd ef", "actual ConfigView key path calls host setter"); view.key(ConfigView.Key.A, "", true, false, false); view.key(ConfigView.Key.C, "", true, false, false); equal(host.clipboard, "abZcd ef", "actual ConfigView copy uses controller clipboard"); view.key(ConfigView.Key.ESCAPE, "", false, false, false); equal(host.values.get("actual"), "abcd ef", "actual ConfigView Escape restores focus baseline"); check(!view.textInputController().focused(), "actual ConfigView Escape releases focus"); check(host.errors.isEmpty(), "actual ConfigView surfaced no interaction errors"); view.dispose();
    }
    private static void drawingAndReadOnly() {
        Test t = new Test(); TextEdit edit = editor("ab", false); Rect r = new Rect(20, 20, 100, 15); TextInputController.Style style = new TextInputController.Style(13).lineHeight(15);
        t.begin(); t.field("bare", edit, r, style, value -> {}, null); t.end(); equal(t.painter.rectangles.size(), 0, "unfocused bare field draws no outer frame"); check(t.painter.texts.stream().anyMatch(text -> text.text().equals("ab") && text.size() == 13), "bare field uses source 13sp size");
        t.input.focus(t, "bare", true); t.begin(); t.field("bare", edit, r, style, value -> {}, null); t.end(); check(!t.painter.rectangles.isEmpty(), "focused selection drawn"); for (Rect rect : t.painter.rectangles) check(rect.h() <= 15 && rect.w() <= 100, "selection geometry stays in field bounds"); equal(t.painter.saves, 0, "bare painter save/restore balanced");
        style.readOnly = true; t.begin(); t.field("bare", edit, r, style, value -> {}, null); t.end(); t.key(ConfigView.Key.NONE, "replacement", false, false); equal(edit.text(), "ab", "read-only text cannot change"); t.key(ConfigView.Key.C, "", true, false); equal(t.host.clipboard, "ab", "read-only selection can be copied");
        t.input.blur(t); TextEdit path = editor("C:/music/song.flac", false); TextInputController.Style pathStyle = single(); pathStyle.path = true; t.begin(); t.field("path", path, r, pathStyle, value -> {}, null); t.end(); check(t.painter.texts.stream().anyMatch(text -> text.text().equals("C:/music/")), "path parent renders as its own muted span"); check(t.painter.texts.stream().anyMatch(text -> text.text().equals("song.flac")), "path filename retains its own visible span"); equal(path.text(), "C:/music/song.flac", "path styling never transforms stored path");
    }
    public static void main(String[] args) { model(); pointerAndSelection(); keyboardSessions(); singleLinePasteTransformation(); layoutAndNavigation(); tabAndModal(); cleanupAndScrolling(); drawingAndReadOnly(); realViewIntegration(); System.out.println("Text input harness passed: " + checks + " interaction assertions."); }
}
